effect.frag.content:
uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec2 p = (v_uv - vec2(0.5)) * 2.0;
  float radius = max(abs(p.x), abs(p.y));
  float depth = 0.25 / max(radius, 0.025);
  vec2 uv = vec2(fract(atan(p.y, p.x) / TAU * 4.0), fract(depth - u_progress));
  vec4 c = sourceAt((uv - 0.5) / (0.7 + u_amount * 0.3) + 0.5);
  c.rgb *= min(1.0, radius * 1.8);
  fragColor = radius < 0.025 ? vec4(0.0) : c;
}
